function initials(name: string | undefined): string {
  if (!name) return '—'
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? '')
    .join('')
}

export function AppLayout() {
  const dispatch = useAppDispatch()
  const navRef = useRef<HTMLElement>(null)
  const [indicatorStyle, setIndicatorStyle] = useState({ left: 0, transform: 'translateX(0px)', width: 0, opacity: 0 })
  const location = useLocation()

  useEffect(() => {
    const updateIndicator = () => {
      if (!navRef.current) return
      
      // Look for the active class first
      let activeTab = navRef.current.querySelector('a.active') as HTMLElement
      
      // Fallback: match href to location
      if (!activeTab) {
        const tabs = Array.from(navRef.current.querySelectorAll('a'))
        activeTab = tabs.find(tab => tab.getAttribute('href') === location.pathname) as HTMLElement
      }
      
      if (activeTab) {
        setIndicatorStyle({
          left: 0,
          transform: `translateX(${activeTab.offsetLeft}px)`,
          width: activeTab.offsetWidth,
          opacity: 1
        })
      }
    }
    // Update once immediately (DOM is updated by React)
    updateIndicator()
    
    // Fallback for fonts/icons loading causing layout shifts
    const raf = requestAnimationFrame(() => {
      requestAnimationFrame(updateIndicator)
    })
    
    return () => cancelAnimationFrame(raf)
  }, [location.pathname])
  
  const user = useAppSelector((state) => state.auth.user)
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    // localStorage is absent under jsdom in the test environment, and can throw
    // when site data is blocked. Never let theme persistence break rendering.
    try {
      return (globalThis.localStorage?.getItem('fv-theme') as 'light' | 'dark') || 'light'
    } catch {
      return 'light'
    }
  })

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme)
  }, [theme])

  const toggleTheme = () => {
    const nextTheme = theme === 'light' ? 'dark' : 'light'
    setTheme(nextTheme)
    document.documentElement.setAttribute('data-theme', nextTheme)
    try {
      globalThis.localStorage?.setItem('fv-theme', nextTheme)
    } catch {
      // persistence is a convenience; ignore a blocked or unavailable store
    }
  }

  const isUnverifiedDoctor = user?.role === 'DOCTOR' && user?.verificationStatus !== 'VERIFIED'
  // Family heads are auto-approved (PR #73); this now only fires when an admin rejects or suspends one.
  const isUnverifiedFamilyHead =
    (user?.role === 'FAMILY_HEAD' || user?.role === 'ONBOARDING') && user?.familyHeadVerificationStatus !== 'VERIFIED'

  const visibleItems = navItems.filter((item) => {
    if (!user || !item.roles.includes(user.role)) return false
    if (isUnverifiedDoctor) return item.path === '/doctor-status'
    if (isUnverifiedFamilyHead) return item.path === '/family-head-status'
    if (item.path === '/doctor-status' || item.path === '/family-head-status') return false
    return true
  })

  const brandDestination = isUnverifiedDoctor
    ? '/doctor-status'
    : isUnverifiedFamilyHead
      ? '/family-head-status'
      : user?.role === 'ONBOARDING'
        ? '/onboarding'
        : '/dashboard'

  async function signOut() {
    try { await apiClient.post('/auth/logout') }
    finally { dispatch(signedOut()) }
  }

  return (
    <div className="app-shell">
      <a className="skip-link" href="#main-content">Skip to main content</a>
      <header className="app-header">
        <div className="app-header-top">
          <NavLink className="brand" to={brandDestination} aria-label="Family Veda dashboard">
            <span className="brand-mark">
              <img src={markUrl} alt="" width={32} height={32} />
            </span>
            <span className="brand-text">
              <strong>Family Veda</strong>
              <small>{user ? portalName[user.role].toUpperCase() : 'PORTAL'}</small>
            </span>
          </NavLink>

          <div className="header-actions">
            <button
              type="button"
              className={`theme-pill-toggle ${theme}`}
              onClick={toggleTheme}
              title={`Switch to ${theme === 'light' ? 'Dark' : 'Light'} theme`}
              aria-label={`Switch to ${theme === 'light' ? 'Dark' : 'Light'} theme`}
            >
              <span className="theme-toggle-text">{theme === 'light' ? 'DAY MODE' : 'NIGHT MODE'}</span>
              <div className="theme-pill-indicator">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="theme-icon sun-icon"><circle cx="12" cy="12" r="5"></circle><line x1="12" y1="1" x2="12" y2="3"></line><line x1="12" y1="21" x2="12" y2="23"></line><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"></line><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"></line><line x1="1" y1="12" x2="3" y2="12"></line><line x1="21" y1="12" x2="23" y2="12"></line><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"></line><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"></line></svg>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="theme-icon moon-icon"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg>
              </div>
            </button>
            
            {user && <NotificationBell />}
            
            <div className="profile-menu">
              <button type="button" className="avatar-btn" aria-haspopup="true" aria-expanded="false">
                <span className="avatar" aria-hidden="true">{initials(user?.name)}</span>
                <span className="avatar-name">{user?.name?.split(' ')[0]}</span>
              </button>
              <div className="profile-dropdown">
                <div className="profile-header">
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <strong>{user?.name}</strong>
                    {user?.role === 'DOCTOR' && user?.verificationStatus === 'VERIFIED' && (
                      <div className="verified-badge" title="Verified Doctor">
                        <svg viewBox="0 0 24 24" aria-label="Verified" role="img" className="verified-badge-icon">
                          <path d="M22.5 12.5c0-1.58-.875-2.95-2.148-3.6.154-.435.238-.905.238-1.4 0-2.21-1.71-3.998-3.918-3.998-.47 0-.92.084-1.336.25C14.818 2.415 13.51 1.5 12 1.5s-2.816.917-3.337 2.25c-.416-.165-.866-.25-1.336-.25-2.21 0-3.918 1.792-3.918 3.998 0 .495.084.965.238 1.4-1.273.65-2.148 2.02-2.148 3.6 0 1.46.727 2.73 1.832 3.475-.06.335-.09.68-.09 1.025 0 2.21 1.71 3.998 3.918 3.998.536 0 1.05-.122 1.517-.34C9.176 21.6 10.495 22.5 12 22.5c1.505 0 2.824-.9 3.53-2.25.467.218.98.34 1.517.34 2.21 0 3.918-1.792 3.918-3.998 0-.345-.03-.69-.09-1.025 1.105-.745 1.832-2.015 1.832-3.475z" fill="currentColor"></path>
                          <path d="M16.91 8.572L10.33 15.68l-3.24-3.24-1.415 1.414 4.655 4.656 7.994-8.65z" fill="var(--surface)"></path>
                        </svg>
                        <span className="sr-only">VERIFIED</span>
                      </div>
                    )}
                  </div>
                  <small className="role-text">{user ? portalName[user.role].toUpperCase() : 'USER'}</small>
                </div>
                <div className="dropdown-actions">
                  <NavLink to={brandDestination} className="dropdown-item">DASHBOARD</NavLink>
                  <NavLink to="/profile" className="dropdown-item">PROFILE SETTINGS</NavLink>
                  <button type="button" className="dropdown-item text-danger" onClick={() => void signOut()}>
                    LOG OUT
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="app-header-bottom">
          <nav className="premium-nav" aria-label="Primary navigation" ref={navRef}>
            {visibleItems.map((item) => (
              <NavLink 
                key={item.path} 
                to={item.path} 
                className={({ isActive }) => isActive ? 'active' : undefined}
              >
                {item.icon && <span className="nav-icon">{item.icon}</span>}
                <span className="nav-label">{item.label}</span>
              </NavLink>
            ))}
            <div 
              key="nav-indicator"
              className="nav-indicator" 
              style={{ 
                position: 'absolute',
                bottom: 0,
                height: '2px',
                background: 'var(--primary)',
                borderRadius: '2px 2px 0 0',
                pointerEvents: 'none',
                left: 0,
                transform: indicatorStyle.transform,
                width: `${indicatorStyle.width}px`, 
                opacity: indicatorStyle.opacity,
                transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)'
              }} 
            />
          </nav>
        </div>
      </header>

      <div className="app-main" style={{ padding: '24px clamp(16px, 2.5vw, 40px)' }}>
        <main id="main-content" className="main-content" tabIndex={-1} style={{ paddingTop: 0 }}>
          {user?.role === 'MEMBER' && <HeadTransferBanner />}
          <Outlet />
        </main>
        <footer className="app-footer">
          Clinical decision-support system. Access is controlled and activity is audited.
        </footer>
      </div>
    </div>
  )
}
